/// The input of main/place.

final class FnMainPlaceInput {
  const FnMainPlaceInput({this.coupon, required this.items});

  factory FnMainPlaceInput.fromJson(Map<String, Object?> json) => FnMainPlaceInput(
        coupon: json['coupon'] == null ? null : json['coupon'] as String,
        items: [for (final e in json['items'] as List) e as String],
      );

  final String? coupon;
  final List<String> items;

  Map<String, Object?> toJson() => {
        'coupon': coupon,
        'items': items,
      };
}

