enum ShopConfigTreeShopCurrency {
  eur('eur'),
  usd('usd');

  const ShopConfigTreeShopCurrency(this.value);

  /// The JSON value.
  final String value;

  /// The member whose value is [v], or null.
  static ShopConfigTreeShopCurrency? maybeValue(Object? v) {
    for (final e in values) {
      if (e.value == v) return e;
    }
    return null;
  }
}

final class ShopConfigTreeShop {
  const ShopConfigTreeShop({this.currency});

