  Map<String, Object?> toJson() => {
        'currency': currency?.value,
      };
}

final class ShopConfigTree {
  const ShopConfigTree({this.maintenance, this.shop});

  factory ShopConfigTree.fromJson(Map<String, Object?> json) => ShopConfigTree(
        maintenance: json['maintenance'] == null ? null : ShopConfigTreeMaintenance.fromJson(Map<String, Object?>.from(json['maintenance'] as Map)),
        shop: json['shop'] == null ? null : ShopConfigTreeShop.fromJson(Map<String, Object?>.from(json['shop'] as Map)),
      );

  final ShopConfigTreeMaintenance? maintenance;
  final ShopConfigTreeShop? shop;

  Map<String, Object?> toJson() => {
        'maintenance': maintenance?.toJson(),
        'shop': shop?.toJson(),
      };
}

