/// The app configuration's leaf paths, typed.
final class ShopConfig {
  ShopConfig(this._config);

  final Config _config;

  /// The "maintenance.enabled" path.
  Future<bool?> maintenanceEnabled({bool refresh = false, RequestOptions? options}) async {
    final v = await _config.get('maintenance.enabled', refresh: refresh, options: options);
    return v as bool?;
  }

  /// The "shop.currency" path.
  Future<ShopConfigShopCurrency?> shopCurrency({bool refresh = false, RequestOptions? options}) async {
    final v = await _config.get('shop.currency', refresh: refresh, options: options);
    return ShopConfigShopCurrency.maybeValue(v);
  }
}

/// The roles "shop" declares.
abstract final class ShopRole {
  static const String admin = 'admin';
  static const String member = 'member';
}

/// The "main" database of "shop", typed.
final class ShopMain {
  ShopMain(this._db);

  final Database _db;

  /// The "invoices" collection.
  TypedCollection<MainInvoices, MainInvoicesInput, MainInvoicesCreate> get invoices =>
      TypedCollection(_db.collection('invoices'), MainInvoices.fromJson, (i) => i.toJson(), (i) => i.toJson());

  /// The "orders" collection.
  TypedCollection<MainOrders, MainOrdersInput, MainOrdersInput> get orders =>
      TypedCollection(_db.collection('orders'), MainOrders.fromJson, (i) => i.toJson(), (i) => i.toJson());

  /// Calls main/place.
  Future<FnMainPlaceOutput> place(FnMainPlaceInput input, {String? idempotencyKey, RequestOptions? options}) async {
    final result = await _db.fn('place', input.toJson(), idempotencyKey: idempotencyKey, options: options);
    return FnMainPlaceOutput.fromJson(Map<String, Object?>.from(result as Map));
  }

  /// Calls main/price.
  Future<FnMainPriceOutput> price(FnMainPriceInput input, {String? idempotencyKey, RequestOptions? options}) async {
    final result = await _db.fn('price', input.toJson(), idempotencyKey: idempotencyKey, options: options);
    return FnMainPriceOutput.fromJson(Map<String, Object?>.from(result as Map));
  }
}

/// The "shop" realm bound to a client: `client.typed` gives it.
final class ShopRealm {
  ShopRealm(this.client);

  final BackdClient<ShopRealm> client;

  /// The "main" database.
  ShopMain get main => ShopMain(client.db('main'));

  /// The realm's app configuration, typed per path.
  ShopConfig get config => ShopConfig(client.config);
}

/// `BackdClient<ShopRealm>` binds the realm's types: `client.typed`.
extension ShopRealmAccess on BackdClient<ShopRealm> {
  ShopRealm get typed => ShopRealm(this);
}
